"""A draggable, keyboard accessible orbit of offline tactics themes."""
import streamlit as st
import base64
from pathlib import Path
from tactics import THEMES
from tactic_art import theme_symbol


# Stable colors belong to themes, even when the selection order changes.
THEME_COLORS = {
    'mix':'#d2a34c', 'fork':'#e75b52', 'pin':'#4288e5',
    'skewer':'#a66de0', 'discoveredAttack':'#35b584',
    'mateIn1':'#f18438', 'mateIn2':'#e35e9c', 'backRankMate':'#42becb',
    'hangingPiece':'#a6bd42', 'deflection':'#6371ce', 'sacrifice':'#b93356',
    'endgame':'#b18c66', 'attraction':'#cc79c6', 'clearance':'#69c299',
    'interference':'#c2693f', 'intermezzo':'#8d9cdb', 'promotion':'#e6c249',
    'underPromotion':'#6aabdf', 'doubleCheck':'#db8176', 'smotheredMate':'#677e43',
}


@st.cache_data(show_spinner=False)
def machine_art():
    """Packaged artwork stays available offline, including the desktop build."""
    asset=Path(__file__).resolve().parent/'assets'/'tactics-gumball-cinematic.png'
    return 'data:image/png;base64,'+base64.b64encode(asset.read_bytes()).decode('ascii')

@st.cache_data(show_spinner=False)
def gum_art():
    asset=Path(__file__).resolve().parent/'assets'/'tactics-gumballs-realistic.png'
    return 'data:image/png;base64,'+base64.b64encode(asset.read_bytes()).decode('ascii')


@st.cache_data(show_spinner=False)
def coin_art():
    asset=Path(__file__).resolve().parent/'assets'/'tactics-coin-aged-metal.png'
    return 'data:image/png;base64,'+base64.b64encode(asset.read_bytes()).decode('ascii')


