def render_orbit(choose_theme,token):
    def selected():
        event=st.session_state.tactics_orbit.select
        if (isinstance(event,dict) and event.get('token')==token
                and event.get('theme') in THEMES.values() and event.get('minutes') in (1,3,5)):
            st.session_state.tactic_duration_seconds=event['minutes']*60
            choose_theme(event['theme'])
    ORBIT(data=dict(themes=[dict(id=value,label=label,art=theme_symbol(value),color=THEME_COLORS[value],sprite=list(THEME_COLORS).index(value)) for label,value in THEMES.items()],token=token,machine=machine_art(),gums=gum_art(),coin=coin_art()),key='tactics_orbit',on_select_change=selected)
